import threading

class SafeBox:
    def __init__(self):
        self.lock = threading.Lock()
        self.count = 0

    def bump(self, n: int) -> int:
        acquired = self.lock.acquire(timeout=1.0)
        if not acquired:
            raise TimeoutError('busy')
        try:
            self.count += n
            return self.count
        finally:
            self.lock.release()

